from kit5 import *

def living(inner='', floor='#c8a070'):
    return R(0, 0, 200, 200, '#f2ead8') + R(0, 150, 200, 50, floor) + inner
_CID = [0]
def tvbox(x, y, w, h, inner='', scr='#9fd0ec'):
    _CID[0] += 1; cid = 'tv%d' % _CID[0]
    return R(x, y, w, h, '#2f3437', 6) + R(x + 5, y + 5, w - 10, h - 10, scr, 2) + '<clipPath id="%s"><rect x="%s" y="%s" width="%s" height="%s"/></clipPath><g clip-path="url(#%s)">' % (cid, x + 5, y + 5, w - 10, h - 10, cid) + inner + '</g>'
def tv_stand(x, y, w, h, inner='', scr='#9fd0ec'):
    return tvbox(x, y, w, h, inner, scr) + R(x + w / 2 - 6, y + h, 12, 10, '#5d6469') + R(x + w / 2 - 30, y + h + 8, 60, 6, '#5d6469', 3)
def remote(x, y, s=1, rot=0):
    return G(R(-12, -40, 24, 80, '#2f3437', 8) + Ci(0, -26, 6, '#e2463b') + ''.join(Ci(-5 + (k % 2) * 10, -8 + (k // 2) * 10, 3, '#a7adb1') for k in range(6)), f'translate({x},{y}) rotate({rot}) scale({s})')
def gamepad(x, y, s=1, col='#2f3437'):
    return G(Pa('M-60,-20 Q-60,-34 -44,-34 L44,-34 Q60,-34 60,-20 L70,20 Q74,40 56,40 Q44,40 36,22 L-36,22 Q-44,40 -56,40 Q-74,40 -70,20 Z', col) + R(-44, -14, 8, 24, '#a7adb1', 2) + R(-52, -6, 24, 8, '#a7adb1', 2) + Ci(36, -12, 6, '#e2463b') + Ci(48, -2, 6, '#3c7fc1') + Ci(24, -2, 6, '#5ba644') + Ci(36, 8, 6, '#f3c234'), f'translate({x},{y}) scale({s})')
def tv_scene(inner, scr='#9fd0ec', extra=''):
    return living(sofa(100, 196, 140, '#5aa1d4', .55) + R(30, 140, 140, 10, '#8a5a35', 3) + tv_stand(36, 30, 128, 86, inner, scr) + extra)
def book_open(x, y, s=1, col='#3c7fc1', lines=True):
    return open_book(x, y, s, col)
def dragon_(x, y, s=1, col='#5ba644'):
    return G(Pa('M-60,20 Q-30,-10 0,10 Q30,30 50,0 Q60,-16 76,-14 L84,-24 L86,-10 Q96,-6 92,4 L80,6 Q70,20 50,30 Q20,50 -20,40 Q-50,40 -80,60 Q-70,40 -60,20 Z', col) + Pa('M-20,10 L-40,-50 L0,-10 Z', shade(col, -.15)) + Pa('M10,14 L20,-40 L36,6 Z', shade(col, -.15)) + Ci(84, -10, 3, '#2f3437') + ''.join(Pa(f'M{-50+k*20},{22-k*2} l6,-12 l6,10 Z', '#f3c234') for k in range(5)) + St('M94,0 q10,-4 14,4', '#e2463b', 3), f'translate({x},{y}) scale({s})')
def wand(x, y, s=1, rot=-30):
    return G(R(-3, 0, 6, 80, '#3a2a20', 3) + R(-3, 0, 6, 10, '#ffffff', 2) + star(0, -6, 10, '#f3c234'), f'translate({x},{y}) rotate({rot}) scale({s})')
def sparkles(pts, col='#f3c234'):
    return ''.join(Pa(f'M{x},{y-r} L{x+r*.25},{y-r*.25} L{x+r},{y} L{x+r*.25},{y+r*.25} L{x},{y+r} L{x-r*.25},{y+r*.25} L{x-r},{y} L{x-r*.25},{y-r*.25} Z', col) for x, y, r in pts)
def witch_hat(x, y, s=1, col='#2f3437'):
    return G(E(0, 0, 50, 10, col) + Pa('M-28,-2 L10,-90 L28,-2 Z', col) + R(-27, -14, 54, 8, '#7a4fa0'), f'translate({x},{y}) scale({s})')
def die(x, y, s=1, n=5, rot=0, col='#ffffff'):
    pos = {1: [(0, 0)], 2: [(-12, -12), (12, 12)], 3: [(-12, -12), (0, 0), (12, 12)], 4: [(-12, -12), (12, -12), (-12, 12), (12, 12)], 5: [(-12, -12), (12, -12), (0, 0), (-12, 12), (12, 12)], 6: [(-12, -12), (12, -12), (-12, 0), (12, 0), (-12, 12), (12, 12)]}[n]
    return G(R(-24, -24, 48, 48, col, 8, 'stroke="#c4cbd0" stroke-width="2"') + ''.join(Ci(dx, dy, 5, '#e2463b' if n == 1 else '#2f3437') for dx, dy in pos), f'translate({x},{y}) rotate({rot}) scale({s})')
def card_play(x, y, s=1, rot=0, suit='♥', col='#e2463b', rank='A'):
    return G(R(-30, -42, 60, 84, '#ffffff', 6, 'stroke="#c4cbd0" stroke-width="2"') + T(-18, -24, rank, 14, col, 900) + T(0, 14, suit, 34, col, 900), f'translate({x},{y}) rotate({rot}) scale({s})')
def chessboard(x, y, n, sz, c1='#f0d9b5', c2='#b58863'):
    return ''.join(R(x + i * sz, y + j * sz, sz, sz, c1 if (i + j) % 2 == 0 else c2) for i in range(n) for j in range(n))
def pawn(x, base, s=1, col='#2f3437'):
    return G(Ci(0, -40, 9, col) + Pa('M-8,-32 L8,-32 L12,-6 L-12,-6 Z', col) + R(-16, -8, 32, 8, col, 3), f'translate({x},{base}) scale({s})')
def knight(x, base, s=1, col='#ffffff'):
    return G(Pa('M-14,0 L-12,-24 Q-20,-34 -10,-48 L0,-56 L4,-48 Q20,-44 16,-24 L14,0 Z', col, 'stroke="#5d6469" stroke-width="2"') + Ci(-2, -42, 2, '#2f3437') + R(-18, -6, 36, 8, col, 3, 'stroke="#5d6469" stroke-width="2"'), f'translate({x},{base}) scale({s})')
def xq_piece(x, y, ch, col='#c0283a', r=22):
    return Ci(x, y, r, '#f0d8a0', 'stroke="#8a5a35" stroke-width="2"') + Ci(x, y, r * .78, 'none', f'stroke="{col}" stroke-width="1.5"') + T(x, y + r * .4, ch, r * 1.05, col, 900, family='KaiTi, STKaiti, serif')
def mj_tile(x, y, s=1, face='', col='#2f6a3a'):
    return G(R(-20, -28, 40, 56, '#5ba644', 6) + R(-20, -28, 40, 50, '#ffffff', 6) + face, f'translate({x},{y}) scale({s})')
def crayon(x, y, s=1, rot=0, col='#e2463b'):
    return G(R(-50, -8, 80, 16, col, 3) + R(-40, -8, 50, 16, shade(col, -.15)) + Pa('M30,-8 L50,0 L30,8 Z', shade(col, .1)), f'translate({x},{y}) rotate({rot}) scale({s})')
def needle_(x, y, s=1, rot=-40):
    return G(Pa('M0,-60 Q3,-56 3,-40 L1,50 L0,60 L-1,50 L-3,-40 Q-3,-56 0,-60 Z', '#a7adb1') + E(0, -48, 1.5, 6, '#ffffff'), f'translate({x},{y}) rotate({rot}) scale({s})')
def spool(x, y, s=1, col='#e2463b'):
    return G(R(-24, -34, 48, 8, '#d9a868', 3) + R(-24, 26, 48, 8, '#d9a868', 3) + R(-18, -26, 36, 52, col) + ''.join(L(-18, -20 + k * 8, 18, -18 + k * 8, shade(col, -.15), 1) for k in range(6)), f'translate({x},{y}) scale({s})')
def yarn_ball(x, y, r, col='#ef8fa4'):
    return Ci(x, y, r, col) + ''.join(St(f'M{x-r*math.cos(a)},{y-r*math.sin(a)} Q{x},{y} {x+r*math.cos(a+.6)},{y+r*math.sin(a+.6)}', shade(col, -.15), 2) for a in [k * .6 for k in range(6)])
def easel_(x, base, s=1, inner=''):
    return G(L(-30, 0, 0, -150, '#a8703e', 6) + L(30, 0, 0, -150, '#a8703e', 6) + L(0, -150, 0, 0, '#8a5a35', 4) + R(-44, -130, 88, 70, '#ffffff', 2) + inner + R(-48, -60, 96, 6, '#a8703e', 2), f'translate({x},{base}) scale({s})')
def ink_stone(x, y, s=1):
    return G(R(-50, -30, 100, 60, '#3a3a3a', 10) + E(-10, 0, 30, 18, '#1a1a1a') + E(30, -10, 12, 8, '#2a2a2a') + hi(-20, -6, 10, 4, .2), f'translate({x},{y}) scale({s})')
def brush_cn(x, y, s=1, rot=-30):
    return G(R(-4, -80, 8, 90, '#c8a070', 3) + R(-5, -84, 10, 8, '#2f3437', 2) + Pa('M-6,10 Q-8,30 0,44 Q8,30 6,10 Z', '#2f3437'), f'translate({x},{y}) rotate({rot}) scale({s})')
def seal_stamp(x, y, s=1, ch='印'):
    return G(R(-20, -40, 40, 40, '#c8a070', 4) + R(-24, 0, 48, 14, '#a8703e', 3) + R(-26, 20, 52, 52, 'none', 4, 'stroke="#e2463b" stroke-width="5"') + T(0, 60, ch, 34, '#e2463b', 900, family='KaiTi, STKaiti, serif'), f'translate({x},{y}) scale({s})')
def canvas_(x, y, w, h, inner=''):
    return R(x, y, w, h, '#ffffff') + R(x, y, w, h, 'none', 0, 'stroke="#d9c8a8" stroke-width="5"') + inner

